WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY opened_date, id) AS row_num FROM accounts) x WHERE row_num = 1) SELECT s.id, s.customer_id, s.account_type, s.balance, s.opened_date, s.status, s.row_num, CASE WHEN status RLIKE '^(OPEN|FROZEN)$' THEN 'GROUP_A' WHEN status RLIKE '^(CLOSED)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS status_zone, (SELECT MAX(t2.monthly_fee) FROM subscriptions t2 WHERE t2.customer_id = s.customer_id) AS max_subscription_monthly_fee FROM ranked s
